const A='/api/index?action=',S={page:'numbers',connected:false,hubs:[],hub:'',projects:[],projectSel:new Set(),preview:[],users:[],companies:[],userSel:new Set(),search:'',userSearch:'',companyFilter:'all',target:'',results:[]};const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),api=async(a,o={})=>{const r=await fetch(A+a,{credentials:'include',headers:{'Content-Type':'application/json'},...o}),d=await r.json();if(!r.ok)throw new Error(d.message);return d};function tbl(h,rows){return `<div class="table"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}function vp(){const q=S.search.toLowerCase();return S.projects.filter(p=>[p.name,p.jobNumber,p.status,p.id].some(v=>String(v).toLowerCase().includes(q)))}function vu(){const q=S.userSearch.toLowerCase();return S.users.filter(u=>(S.companyFilter==='all'||u.company===S.companyFilter)&&[u.name,u.email,u.company,u.status].some(v=>String(v).toLowerCase().includes(q)))}function render(){const target=S.companies.find(c=>c.id===S.target),pm=new Map(S.preview.map(x=>[x.id,x]));$('#app').innerHTML=`<div class="wrap"><div class="bar"><h1 class="grow">Company Manage v31</h1><button id="auth" class="btn">${S.connected?'Sign out':'Connect Autodesk'}</button></div><div class="card bar"><button data-tab="numbers" class="btn ${S.page==='numbers'?'':'light'}">Project Numbers</button><button data-tab="company" class="btn ${S.page==='company'?'':'light'}">Bulk User Company</button><select id="hub" class="select grow">${S.hubs.map(h=>`<option value="${h.id}" ${h.id===S.hub?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div><div id="err"></div>${S.page==='numbers'?`<div class="notice"><b>Job number only.</b> Project names are never changed.</div><div class="card"><div class="bar"><input id="search" class="input grow" value="${esc(S.search)}" placeholder="Search project name, job number, status or ID"><button id="loadProjects" class="btn">Load Projects</button><button id="allProjects" class="btn soft">Select All Filtered</button><button id="clearProjects" class="btn light">Deselect All</button><span class="badge">${S.projectSel.size} selected</span></div><div class="bar"><select id="op" class="select"><option value="addPrefix">Add Prefix</option><option value="removePrefix">Remove Prefix</option><option value="addSuffix">Add Suffix</option><option value="removeSuffix">Remove Suffix</option><option value="set">Replace Full Job Number</option></select><input id="value" class="input grow"><button id="preview" class="btn soft">Preview</button><button id="applyJobs" class="btn">Apply</button></div>${tbl(['Select','Project Name (unchanged)','Current Job Number','Proposed Job Number','Status'],vp().map(p=>{const x=pm.get(p.id);return[`<input class="pp" data-id="${p.id}" type="checkbox" ${S.projectSel.has(p.id)?'checked':''}>`,esc(p.name),esc(p.jobNumber),esc(x?.proposedJobNumber||''),esc(p.status)]}))}</div>`:`<div class="notice">Change selected users' default Hub company using <code>company_id</code>.</div><div class="card"><div class="bar"><button id="loadUsers" class="btn">Load Hub Users</button><button id="loadCompanies" class="btn">Load Companies</button><input id="userSearch" class="input grow" value="${esc(S.userSearch)}" placeholder="Search name, email, company or status"><select id="companyFilter" class="select"><option value="all">All current companies</option>${[...new Set(S.users.map(u=>u.company).filter(Boolean))].sort().map(c=>`<option ${S.companyFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="bar"><button id="allUsers" class="btn soft">Select All Filtered</button><button id="clearUsers" class="btn light">Deselect All</button><span class="badge">${S.userSel.size} selected</span><select id="target" class="select grow"><option value="">Select target company</option>${S.companies.map(c=>`<option value="${c.id}" ${S.target===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button id="applyCompany" class="btn" ${S.userSel.size&&target?'':'disabled'}>Apply Company Change</button></div>${tbl(['Select','User','Email','Current Company','Status','Target Company'],vu().map(u=>[`<input class="up" data-id="${u.id}" type="checkbox" ${S.userSel.has(u.id)?'checked':''}>`,esc(u.name),esc(u.email),esc(u.company),esc(u.status),esc(target?.name||'')]))}</div>`}</div>`;bind()}async function loadPaged(type){let out=[],o=0,total=1;while(o<total){const d=await api(`${type}-page&hubId=${encodeURIComponent(S.hub)}&offset=${o}`);out.push(...d.items);total=d.total;o=d.nextOffset}if(type==='projects')S.projects=out;if(type==='hub-users')S.users=out;if(type==='companies')S.companies=out;render()}function preview(){const op=$('#op').value,val=$('#value').value;S.preview=S.projects.filter(p=>S.projectSel.has(p.id)).map(p=>{let j=String(p.jobNumber||'');if(op==='addPrefix')j=val+j;if(op==='removePrefix'&&j.startsWith(val))j=j.slice(val.length);if(op==='addSuffix')j+=val;if(op==='removeSuffix'&&val&&j.endsWith(val))j=j.slice(0,-val.length);if(op==='set')j=val;return{...p,proposedJobNumber:j}});render()}async function applyJobs(){const d=await api('project-job-numbers',{method:'POST',body:JSON.stringify({hubId:S.hub,projects:S.preview})});S.results=d.results;const ok=new Map(d.results.filter(x=>x.success).map(x=>[x.id,x]));S.projects=S.projects.map(p=>ok.has(p.id)?{...p,jobNumber:ok.get(p.id).proposedJobNumber}:p);S.preview=[];S.projectSel.clear();render()}async function applyCompany(){const c=S.companies.find(x=>x.id===S.target),users=S.users.filter(u=>S.userSel.has(u.id)),d=await api('bulk-user-company',{method:'POST',body:JSON.stringify({hubId:S.hub,companyId:c.id,companyName:c.name,users})});const ok=new Set(d.results.filter(x=>x.success).map(x=>x.id));S.users=S.users.map(u=>ok.has(u.id)?{...u,company:c.name,companyId:c.id}:u);S.results=d.results;S.userSel.clear();render()}function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{S.page=b.dataset.tab;render()});$('#auth').onclick=async()=>S.connected?(await api('auth-logout',{method:'POST'}),location.reload()):(location.href=(await api('auth-login')).url);$('#hub').onchange=e=>S.hub=e.target.value;if($('#loadProjects'))$('#loadProjects').onclick=()=>loadPaged('projects');if($('#search'))$('#search').oninput=e=>{S.search=e.target.value;render()};document.querySelectorAll('.pp').forEach(x=>x.onchange=()=>x.checked?S.projectSel.add(x.dataset.id):S.projectSel.delete(x.dataset.id));if($('#allProjects'))$('#allProjects').onclick=()=>{vp().forEach(p=>S.projectSel.add(p.id));render()};if($('#clearProjects'))$('#clearProjects').onclick=()=>{S.projectSel.clear();render()};if($('#preview'))$('#preview').onclick=preview;if($('#applyJobs'))$('#applyJobs').onclick=applyJobs;if($('#loadUsers'))$('#loadUsers').onclick=()=>loadPaged('hub-users');if($('#loadCompanies'))$('#loadCompanies').onclick=()=>loadPaged('companies');if($('#userSearch'))$('#userSearch').oninput=e=>{S.userSearch=e.target.value;render()};if($('#companyFilter'))$('#companyFilter').onchange=e=>{S.companyFilter=e.target.value;render()};if($('#target'))$('#target').onchange=e=>{S.target=e.target.value;render()};document.querySelectorAll('.up').forEach(x=>x.onchange=()=>x.checked?S.userSel.add(x.dataset.id):S.userSel.delete(x.dataset.id));if($('#allUsers'))$('#allUsers').onclick=()=>{vu().forEach(u=>S.userSel.add(u.id));render()};if($('#clearUsers'))$('#clearUsers').onclick=()=>{S.userSel.clear();render()};if($('#applyCompany'))$('#applyCompany').onclick=applyCompany}async function start(){if(location.pathname==='/callback'){await api('auth-callback&code='+encodeURIComponent(new URLSearchParams(location.search).get('code')||''));location.replace('/');return}const d=await api('auth-status');S.connected=d.authenticated;if(S.connected){const h=await api('hubs');S.hubs=h.hubs;S.hub=h.hubs[0]?.id||''}render()}start().catch(e=>{render();$('#err').innerHTML=`<div class="error">${esc(e.message)}</div>`});